<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,reactive,watch,nextTick} from 'vue';
import {useRoute} from 'vue-router';
import {Activity,ArrowDown,ArrowUp,ArrowUpRight,Bell,Check,CheckCheck,ChevronRight,Clock3,FileText,Folder,GitBranch,GripVertical,LayoutDashboard,ListTodo,LoaderCircle,LogOut,MessageSquare,MoreHorizontal,Pause,Play,Plus,Search,Settings2,ShieldCheck,Square,Terminal,Workflow,X,ExternalLink,AlertCircle,Download,Users,Radio} from 'lucide-vue-next';
import {useTaskStore,api} from './store';
import ProjectActions from './ProjectActions.vue';
import ProjectRemoval from './ProjectRemoval.vue';
import DirectoryPicker from './DirectoryPicker.vue';
import LineLinks from './LineLinks.vue';
import ExecutionApproval from './ExecutionApproval.vue';
import ValidationSkip from './ValidationSkip.vue';
import NotificationManager from './NotificationManager.vue';
const directoryPickerTarget=ref<'project'|'root'|null>(null);
function selectDirectory(path:string){if(directoryPickerTarget.value==='root')projectRootInput.value=path;else if(directoryPickerTarget.value==='project')projectForm.path=path;directoryPickerTarget.value=null;}
const removalCleanup=ref<string[]>([]);
const store=useTaskStore(),route=useRoute();
const concurrencyDraft=ref<number|null>(null);
const concurrencyInput=computed({get:()=>concurrencyDraft.value??store.runner.maxConcurrent,set:(value:number)=>{concurrencyDraft.value=value;}});
const validConcurrency=computed(()=>Number.isInteger(concurrencyInput.value)&&concurrencyInput.value>=1&&concurrencyInput.value<=32);
const projectRootDraft=ref<string|null>(null);
const projectRootInput=computed({get:()=>projectRootDraft.value??store.defaultProjectRoot,set:(value:string)=>{projectRootDraft.value=value;}});
const login=reactive({username:'admin',password:''});const loginError=ref(''),initializing=ref(true),busy=ref(false),toast=ref(''),query=ref(''),filter=ref('all');
const showNew=ref(false),selected=ref<any>(null),tab=ref('overview'),answer=ref(''),files=ref<any[]>([]),users=ref<any[]>([]);
const newTask=reactive({title:'',description:'',projectId:'',type:'code',priority:1,planner:'claude',executor:'codex',reviewer:'claude'});
const projectForm=reactive({name:'',code:'',path:'',createIfMissing:true}),memberForm=reactive({name:'',username:'',password:'',projectIds:[] as string[]}),passwordForm=reactive({current:'',password:''});
const statuses:Record<string,string>={planning:'等待規劃',awaiting_approval:'待審核',queued:'排隊中',running:'執行中',waiting_input:'等待回答',paused:'已暫停',completed:'已完成',repair_planning:'分析修正方案',awaiting_repair_approval:'待審核修正方案',rate_limited:'等待額度恢復',failed:'需要處理',cancelled:'已取消'};
const priorities=['低','一般','高','緊急'];
const nav=[{path:'/',label:'工作總覽',icon:LayoutDashboard},{path:'/tasks',label:'任務佇列',icon:ListTodo},{path:'/threads',label:'角色工作階段',icon:GitBranch},{path:'/settings',label:'平台設定',icon:Settings2}];
const currentNav=computed(()=>nav.find(n=>n.path===route.path)||nav[0]);
const visibleTasks=computed(()=>store.tasks.filter(t=>(filter.value==='all'||t.status===filter.value)&&(!query.value||`${t.title} ${t.projectName} ${t.ownerName}`.toLowerCase().includes(query.value.toLowerCase()))));
const recentTasks=computed(()=>[...store.tasks].sort((a,b)=>Date.parse(b.updated)-Date.parse(a.updated)).slice(0,6));
const attention=computed(()=>store.tasks.filter(t=>['awaiting_approval','awaiting_repair_approval','waiting_input','failed'].includes(t.status)));
const activeThreads=computed(()=>store.tasks.flatMap(t=>t.threads.map((th:any)=>({...th,task:t}))));
const completed=computed(()=>store.tasks.filter(t=>t.status==='completed').length);
const time=(value:string)=>value?new Intl.DateTimeFormat('zh-TW',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(value)):'—';
const duration=(th:any)=>`${Math.max(0,Math.round(((th.finished?new Date(th.finished).getTime():Date.now())-new Date(th.started).getTime())/60000))} 分鐘`;
const percent=(t:any)=>t.status==='completed'?100:t.totalSteps?Math.round(t.completedSteps/t.totalSteps*100):0;
let interval:ReturnType<typeof setInterval>,toastTimer:ReturnType<typeof setTimeout>;
function notify(message:string){toast.value=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',6000);}
async function run(fn:()=>Promise<any>){if(busy.value)return;busy.value=true;try{await fn();await store.refresh();if(selected.value)await loadTask(selected.value.id);}catch(e:any){notify(e.message);}finally{busy.value=false;}}
async function projectRemoved(projectId:string,pendingCleanup:string[]=[]){removalCleanup.value=pendingCleanup;if(selected.value?.projectId===projectId)selected.value=null;if(newTask.projectId===projectId)newTask.projectId='__new__';memberForm.projectIds=memberForm.projectIds.filter(id=>id!==projectId);users.value=await api('/admin/users');notify(pendingCleanup.length?'專案已移除，部分磁碟檔案尚待清理':'專案及磁碟檔案已移除');}
async function signIn(){loginError.value='';try{await api('/login',login);login.password='';await store.refresh();}catch(e:any){loginError.value=e.message;}}
async function loadTask(id:string){selected.value=await api('/tasks/'+id);}
async function openTask(t:any){tab.value='overview';answer.value='';files.value=[];await run(()=>loadTask(t.id));}
async function action(name:string){if(!selected.value)return;await run(async()=>{await api(`/tasks/${selected.value.id}/action`,{action:name,artifactVersion:selected.value.artifactVersion});notify(name==='publish-approve'?'此版成果已核准；尚未對外發布':'任務狀態已更新');});}
async function create(){await run(async()=>{const t=await api('/tasks',{...newTask,projectId:newTask.projectId==='__new__'?undefined:newTask.projectId,createProject:newTask.projectId==='__new__'});showNew.value=false;newTask.title='';newTask.description='';selected.value=await api('/tasks/'+t.id);tab.value='overview';notify('任務已建立');});}
async function setTaskStatus(t:any,event:Event){const select=event.target as HTMLSelectElement;const status=select.value;select.value=t.status;await run(async()=>{await api(`/tasks/${t.id}/status`,{status,expectedStatus:t.status});notify(status==='completed'?'任務已手動完成':'任務狀態已更新');});}
async function setPriority(t:any,event:Event){await run(()=>api(`/tasks/${t.id}/priority`,{priority:Number((event.target as HTMLSelectElement).value)}));}
async function reorder(t:any,direction:number){const list=store.tasks.filter(x=>x.priority===t.priority&&(store.user.role==='admin'||x.ownerId===store.user.id));const i=list.findIndex(x=>x.id===t.id),next=i+direction;if(next<0||next>=list.length)return;[list[i],list[next]]=[list[next],list[i]];await run(()=>api('/reorder',{ids:list.map(x=>x.id)}));}
const dragging=ref<string|null>(null);
const overlay=computed(()=>showNew.value?'new':selected.value?'detail':'none');let previousFocus:HTMLElement|null=null;
watch(overlay,async(value,old)=>{if(old==='none')previousFocus=document.activeElement as HTMLElement;await nextTick();if(value==='none'){previousFocus?.focus();return;}const container=document.querySelector(value==='new'?'.modal':'.drawer');(container?.querySelector('[autofocus],button,input,select,textarea,a[href]') as HTMLElement)?.focus();});
function keyboard(event:KeyboardEvent){if(overlay.value==='none')return;if(event.key==='Escape'){if(showNew.value)showNew.value=false;else selected.value=null;return;}if(event.key!=='Tab')return;const container=document.querySelector(overlay.value==='new'?'.modal':'.drawer');const nodes=Array.from(container?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href],summary')||[]).filter(el=>el.getClientRects().length);const first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
async function drop(target:any){const source=store.tasks.find(t=>t.id===dragging.value);dragging.value=null;if(!source||source.id===target.id)return;if(source.priority!==target.priority){notify('拖曳可調整相同優先級的任務；跨級請使用優先級選單。');return;}const list=store.tasks.filter(t=>t.priority===target.priority);const moved=list.splice(list.findIndex(t=>t.id===source.id),1)[0];list.splice(list.findIndex(t=>t.id===target.id),0,moved);await run(()=>api('/reorder',{ids:list.map(t=>t.id)}));}
watch(()=>newTask.type,type=>{newTask.executor=type==='research'?'claude':'codex';newTask.reviewer=type==='research'?'codex':'claude';});
watch(()=>route.path,async p=>{filter.value='all';query.value='';if(p==='/settings'&&store.user?.role==='admin')try{users.value=await api('/admin/users');}catch(e:any){notify(e.message);}});
watch(tab,async v=>{if(v==='artifacts'&&selected.value)try{files.value=(await api(`/tasks/${selected.value.id}/artifacts`)).files;}catch(e:any){notify(e.message);}});
onMounted(async()=>{document.addEventListener('keydown',keyboard);try{await store.refresh();if(route.path==='/settings'&&store.user?.role==='admin')users.value=await api('/admin/users');}catch{}finally{initializing.value=false;}interval=setInterval(async()=>{if(!store.user||busy.value)return;try{await store.refresh();if(selected.value)await loadTask(selected.value.id);}catch{}},3000);
  const context=(document as any).modelContext;if(context?.registerTool)Promise.resolve(context.registerTool({name:'start_task_creation',description:'Open the task creation form. Does not submit or execute a task.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>{if(!store.user)throw new Error('Sign in first');newTask.projectId=store.user.role==='admin'?'__new__':store.projects[0]?.id||'';showNew.value=true;return {opened:true};}})).catch(()=>{});
});
onUnmounted(()=>{clearInterval(interval);clearTimeout(toastTimer);document.removeEventListener('keydown',keyboard);});
</script>

<template>
  <div v-if="removalCleanup.length" class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="磁碟清理未完成"><h2>部分磁碟檔案尚未刪除</h2><p>專案紀錄已移除，但下列檔案仍被占用。請關閉占用程式後清理這些資料夾；不要視為磁碟清理已完成。</p><ul><li v-for="path in removalCleanup" :key="path" style="overflow-wrap:anywhere">{{path}}</li></ul><button class="secondary" @click="removalCleanup=[]">我知道了</button></section></div>
  <DirectoryPicker v-if="directoryPickerTarget && store.user?.role==='admin'" :title="directoryPickerTarget==='root'?'選擇預設專案存放位置':'選擇專案資料夾'" :initial-path="directoryPickerTarget==='root'?projectRootInput:(projectForm.path||store.defaultProjectRoot)" :suggested-name="directoryPickerTarget==='project'?projectForm.name:''" @close="directoryPickerTarget=null" @select="selectDirectory"/>
  <div v-if="initializing" class="loading-screen"><LoaderCircle class="spin"/> 正在連接本地工作台</div>
  <main v-else-if="!store.user" class="login-screen">
    <div class="login-brand"><div class="brand-icon"><Workflow :size="28"/></div><h1>TaskFlow<span>LOCAL WORKSPACE</span></h1><p>從一個想法，到可驗證的成果。</p><div class="login-line"><span>需求</span><ChevronRight/><span>分工</span><ChevronRight/><span>驗證</span></div></div>
    <form class="login-card" @submit.prevent="signIn"><span class="eyebrow">YOUR WORKSPACE</span><h2>登入工作台</h2><p class="muted">掌握任務、角色與每一步進展。</p><label>帳號<input v-model="login.username" autocomplete="username" required></label><label>密碼<input v-model="login.password" type="password" autocomplete="current-password" required></label><p v-if="loginError" class="error-text" role="alert">{{loginError}}</p><button class="primary">登入 <ArrowUpRight :size="18"/></button><small>首次登入資訊：本機 data/first-login.txt</small></form>
  </main>
  <div v-else class="app-shell">
    <aside class="sidebar"><a class="brand" href="/"><div class="brand-icon"><Workflow :size="22"/></div><div>TaskFlow<small>LOCAL WORKSPACE</small></div></a><div class="workspace-tag"><span class="workspace-avatar">T</span><div>AI 協作空間<small>Windows 本地工作台</small></div></div><div class="nav-label">工作空間</div><nav><RouterLink v-for="n in nav" :key="n.path" :to="n.path" :class="{active:route.path===n.path}"><component :is="n.icon" :size="19"/>{{n.label}}<span v-if="n.path==='/tasks'" class="nav-count">{{store.tasks.length}}</span></RouterLink></nav><div class="sidebar-bottom"><div class="runner-mini"><Radio :size="17"/><div>{{store.runner.enabled?'任務服務已啟用':'任務服務已暫停'}}<small>{{store.runner.busy?'正在處理任務':store.runner.enabled?'等待下一筆工作':'前往設定啟用 AI 執行'}}</small></div></div><div class="profile"><span class="avatar">{{store.user.name.slice(0,1)}}</span><div>{{store.user.name}}<small>{{store.user.role==='admin'?'工作空間管理者':'工作空間成員'}}</small></div><button class="icon-button" title="登出" @click="run(async()=>{await api('/logout',{});store.user=null;selected=null;})"><LogOut :size="17"/></button></div></div></aside>
    <div class="main-shell"><header class="topbar"><div class="breadcrumb">工作空間 <ChevronRight :size="14"/> <strong>{{currentNav.label}}</strong></div><div class="topbar-right"><span class="connection" :class="{offline:store.offline}"><i/>{{store.offline?'連線中斷':'本地已連線'}}</span><button class="icon-button" title="查看待處理任務" @click="$router.push('/tasks');filter='awaiting_approval'"><Bell :size="19"/><span v-if="attention.length" class="notification-dot"/></button><span class="avatar small">{{store.user.name.slice(0,1)}}</span></div></header>
    <main class="content">
      <div v-if="store.offline" class="notice warning"><AlertCircle :size="18"/>無法連接本機服務。目前顯示最後讀取的資料，恢復連線後會更新。</div>
      <div class="page-heading"><div><span class="eyebrow">{{route.path==='/settings'?'WORKSPACE SETTINGS':route.path==='/threads'?'AGENT ACTIVITY':'MISSION CONTROL'}}</span><h1>{{currentNav.label}}</h1><p>{{route.path==='/'?'讓想法持續推進，每一步都有跡可循。':route.path==='/tasks'?'安排下一步工作，讓重要的任務先開始。':route.path==='/threads'?'每個角色專注自己的工作，所有進展集中於此。':'管理成員、專案與本機執行服務。'}}</p></div><button v-if="route.path!=='/settings'" class="primary" @click="showNew=true;newTask.projectId=store.user.role==='admin'?'__new__':store.projects[0]?.id||''"><Plus :size="18"/>發布任務</button></div>
      <template v-if="route.path==='/'">
        <section class="metrics"><div class="metric"><span>進行中的任務 <Activity :size="18"/></span><strong>{{store.tasks.filter(t=>['running','queued','planning'].includes(t.status)).length.toString().padStart(2,'0')}}</strong><small>{{store.runner.busy?'AI 正在工作':'等待下一次派工'}}</small></div><div class="metric"><span>需要你的決定 <MessageSquare :size="18"/></span><strong class="amber">{{attention.length.toString().padStart(2,'0')}}</strong><small>審核、問題與異常</small></div><div class="metric"><span>已完成任務 <CheckCheck :size="18"/></span><strong>{{completed.toString().padStart(2,'0')}}</strong><small>含驗證完成與手動完成</small></div><div class="metric"><span>工作階段 <GitBranch :size="18"/></span><strong>{{activeThreads.length.toString().padStart(2,'0')}}</strong><small>{{activeThreads.filter(t=>t.status==='running').length}} 個正在執行</small></div></section>
        <section v-if="!store.projects.length" class="onboarding"><div class="onboarding-icon"><Folder :size="30"/></div><div><span class="eyebrow">FIRST STEP</span><h2>為第一個任務準備工作空間</h2><p>{{store.user.role==='admin'?'新增一個本機專案，就能發布需求、審核計畫並追蹤 AI 工作。':'請管理者為你分配專案，接著就能建立第一個任務。'}}</p></div><RouterLink v-if="store.user.role==='admin'" to="/settings" class="secondary">設定專案 <ArrowUpRight :size="17"/></RouterLink></section>
        <div class="overview-grid"><section class="panel"><div class="section-heading"><h2>任務動態 <span class="count">{{store.tasks.length}}</span></h2><RouterLink to="/tasks">所有任務 <ArrowUpRight :size="16"/></RouterLink></div><div v-if="!store.tasks.length" class="empty"><div class="empty-icon"><ListTodo :size="30"/></div><h3>下一個成果，從這裡開始</h3><p>描述你想完成的事情，AI 會先整理計畫，<br>經你審核後才開始執行。</p><button class="secondary" @click="showNew=true;newTask.projectId=store.user.role==='admin'?'__new__':store.projects[0]?.id||''"><Plus :size="16"/>建立第一個任務</button></div><button v-for="t in recentTasks" :key="t.id" class="activity-row" @click="openTask(t)"><span class="task-symbol"><FileText v-if="t.type==='research'" :size="19"/><Terminal v-else :size="19"/></span><div class="grow"><strong>{{t.title}}</strong><small>{{t.projectName}} · {{t.ownerName}}</small><small v-if="t.status==='rate_limited'">預計重試：{{time(t.retryAt)}}</small></div><span class="badge" :class="t.status">{{t.manualCompletion?'手動完成':statuses[t.status]}}</span><ChevronRight :size="16"/></button></section>
        <div class="right-stack"><section class="panel attention-panel"><div class="section-heading"><h2>等待你處理</h2><span class="count">{{attention.length}}</span></div><div v-if="!attention.length" class="quiet"><ShieldCheck :size="28"/><h3>目前沒有待確認事項</h3><p>需要審核或補充時，會集中顯示在這裡。</p></div><button v-for="t in attention.slice(0,4)" :key="t.id" class="attention-item" @click="openTask(t)"><strong>{{t.title}}</strong><span>{{statuses[t.status]}} <ArrowUpRight :size="15"/></span></button></section><section class="panel connections"><h2>服務連線</h2><div><span><Terminal :size="17"/> AI 執行服務</span><span class="badge" :class="store.runner.enabled?'completed':'paused'">{{store.runner.enabled?'已啟用':'已暫停'}}</span></div><div><span><MessageSquare :size="17"/> LINE 收件匣</span><span class="badge" :class="store.integrations.lastSync&&!store.integrations.error?'completed':'paused'">{{store.integrations.lastSync&&!store.integrations.error?'已連線':store.integrations.lineConfigured?'待同步':'未設定'}}</span></div><div><span>LINE 通知</span><span class="badge" :class="store.integrations.notificationError?'failed':'completed'">{{store.integrations.notificationError?'傳送失敗':store.integrations.pendingNotifications?'等待傳送':'無待送通知'}}</span></div><p v-if="store.integrations.notificationError" class="error-text">{{store.integrations.notificationError}} · {{store.integrations.pendingNotifications}} 則尚未送出。收件連線正常不代表通知已送達。</p><p>本機關機後，AI 工作暫停；雲端收件需完成連線設定。</p></section></div></div>
      </template>
      <template v-else-if="route.path==='/tasks'">
        <div class="toolbar"><div class="filter-tabs"><button :class="{selected:filter==='all'}" @click="filter='all'">全部 <span>{{store.tasks.length}}</span></button><button :class="{selected:filter==='running'}" @click="filter='running'">執行中</button><button :class="{selected:filter==='awaiting_approval'}" @click="filter='awaiting_approval'">待審核</button><button :class="{selected:filter==='completed'}" @click="filter='completed'">已完成</button></div><label class="search"><Search :size="17"/><input v-model="query" placeholder="搜尋任務、專案或成員" aria-label="搜尋任務"></label></div>
        <div class="queue-note"><GripVertical :size="16"/>拖曳調整同優先級的派工順序；正在執行的工作不會被中斷。</div>
        <section class="panel table-panel"><div class="task-table-head"><span>任務 / 專案</span><span>狀態</span><span>子任務進度</span><span>優先級</span><span>排序</span></div><div v-if="!visibleTasks.length" class="empty"><ListTodo :size="30"/><h3>{{store.tasks.length?'沒有符合條件的任務':'任務佇列還是空的'}}</h3><p>發布任務後，可以在這裡安排順序和追蹤進展。</p></div><div v-for="t in visibleTasks" :key="t.id" class="task-table-row" draggable="true" @dragstart="dragging=t.id" @dragover.prevent @drop.prevent="drop(t)"><button class="task-title" @click="openTask(t)"><GripVertical :size="15" class="muted"/><span><strong>{{t.title}}</strong><small>{{t.projectName}} · {{t.ownerName}}</small><small v-if="t.status==='rate_limited'">預計重試：{{time(t.retryAt)}}</small></span></button><select class="task-status-select" :value="t.status" :aria-label="'修改任務狀態：'+t.title" :disabled="busy" @change="setTaskStatus(t,$event)"><option :value="t.status">{{t.manualCompletion?'手動完成':statuses[t.status]}}</option><option v-if="t.status!=='completed'" value="completed">標記完成</option><option v-if="t.status!=='paused'" value="paused">暫停任務</option><option v-if="t.status!=='cancelled'" value="cancelled">取消任務</option><option v-if="['completed','cancelled','paused','failed','waiting_input'].includes(t.status)" value="reopen">恢復處理</option></select><div class="progress-cell"><small>{{t.totalSteps?`${t.completedSteps} / ${t.totalSteps} 步驟`:'尚待規劃'}}</small><div class="progress-track"><i :style="{width:percent(t)+'%'}"/></div></div><select :value="t.priority" aria-label="任務優先級" @change="setPriority(t,$event)"><option v-for="(p,i) in priorities" :key="i" :value="i">{{p}}</option></select><div class="row-actions"><button class="icon-button" title="向前排序" @click="reorder(t,-1)"><ArrowUp :size="16"/></button><button class="icon-button" title="向後排序" @click="reorder(t,1)"><ArrowDown :size="16"/></button></div></div></section>
      </template>
      <template v-else-if="route.path==='/threads'">
        <div class="notice"><GitBranch :size="18"/>各角色保有獨立的工作紀錄；第一版依任務優先序逐一執行，避免共用檔案互相覆寫。</div><section v-if="!activeThreads.length" class="panel empty"><GitBranch :size="32"/><h3>尚未建立工作階段</h3><p>啟用 AI 服務並發布任務後，角色會出現在這裡。</p></section><div class="thread-grid"><button v-for="th in [...activeThreads].reverse()" :key="th.id" class="thread-card" @click="openTask(th.task);tab='threads'"><div class="thread-card-top"><span class="engine-mark">{{th.engine==='codex'?'C':'A'}}</span><span class="badge" :class="th.displayStatus||th.status">{{th.statusLabel||statuses[th.status]||th.status}}</span></div><h3>{{th.role}}</h3><p>{{th.task.title}}</p><div class="thread-meta"><span>{{th.engine==='codex'?'Codex':'Claude Code'}}</span><span><Clock3 :size="14"/>{{duration(th)}}</span></div><div class="thread-summary">{{th.summary||th.error||'等待引擎回傳工作結果'}}</div></button></div>
      </template>
      <template v-else-if="route.path==='/settings'">
        <div class="settings-grid"><section class="panel settings-card"><h2><Radio :size="20"/>執行服務</h2><p>開啟後，平台會使用本機 CLI 登入，依設定上限規劃並執行已核准的工作。首次使用前請確認兩個引擎已登入。</p><div class="setting-row"><span>AI 自動領取任務<small>同時執行上限：{{store.runner.maxConcurrent}}</small></span><button v-if="store.user.role==='admin'" class="toggle" :class="{on:store.runner.enabled}" :aria-pressed="store.runner.enabled" aria-label="AI 自動領取任務" @click="run(()=>api('/admin/runner',{enabled:!store.runner.enabled}))"><i/></button><span v-else>{{store.runner.enabled?'已啟用':'已暫停'}}</span></div><p class="subtle">關閉會停止後續派工；目前的工作仍會完成。</p><form v-if="store.user.role==='admin'" @submit.prevent="run(async()=>{await api('/admin/runner',{maxConcurrent:concurrencyInput});concurrencyDraft=null;notify('同時執行上限已儲存');})"><label for="runner-concurrency">同時執行上限（1–32 個任務）</label><div class="setting-row"><input id="runner-concurrency" v-model.number="concurrencyInput" type="number" min="1" max="32" step="1" required style="width:100px"/><button class="secondary" :disabled="busy||!validConcurrency||concurrencyInput===store.runner.maxConcurrent">儲存</button></div></form><p class="subtle">目前執行 {{store.runner.activeCount}} 個任務。調低上限不會中斷既有工作；不同任務可並行，同一任務的步驟依序執行。</p></section><LineLinks/><NotificationManager v-if="store.user.role==='admin'"/>
        <section v-if="store.user.role==='admin'" class="panel settings-card wide"><h2><Folder :size="20"/>預設專案存放位置</h2><p>從 LINE 建立專案時，會以專案名稱在此位置建立資料夾。只有管理者可以建立；同名資料夾不會覆蓋。</p><form class="inline-form" @submit.prevent="run(async()=>{const result=await api('/admin/project-root',{path:projectRootInput});projectRootDraft=result.path;notify('預設專案存放位置已儲存');})"><label class="grow">本機存放位置<div class="project-directory-field"><input v-model="projectRootInput" placeholder="請選擇預設存放資料夾" readonly required @click="directoryPickerTarget='root'"><button type="button" class="secondary" @click="directoryPickerTarget='root'"><Folder :size="16"/>選擇資料夾</button></div></label><button class="secondary" :disabled="busy">儲存位置</button></form><p class="subtle">{{store.defaultProjectRoot?'目前位置：'+store.defaultProjectRoot:'尚未設定，設定後即可在 LINE 點選「建立專案」。'}} 可在選擇視窗內瀏覽或建立資料夾，選取後按「儲存位置」套用。電腦關機時，LINE 請求會在本機重新上線後處理。</p></section>
        <section class="panel settings-card wide"><h2><Folder :size="20"/>可用專案</h2><p>只有管理者能指定或建立本機資料夾。AI 使用獨立工作副本，不直接修改原專案。</p><div v-for="p in store.projects" :key="p.id" class="project-row"><Folder :size="19"/><div class="grow"><strong>{{p.name}} <code>{{p.code}}</code></strong><small>{{p.path||'已授權使用'}}</small></div><ProjectRemoval v-if="store.user.role==='admin'" :project="p" @removed="projectRemoved"/><ProjectActions :project="p"/></div><p v-if="!store.projects.length" class="muted">尚無可用專案。</p><form v-if="store.user.role==='admin'" class="inline-form" @submit.prevent="run(async()=>{const result=await api('/admin/projects',projectForm);Object.assign(projectForm,{name:'',code:'',path:'',createIfMissing:true});notify(result.directoryCreated?'資料夾已建立，專案已新增':'專案已新增，使用既有資料夾');})"><label>專案名稱<input v-model="projectForm.name" placeholder="例如：產品官網" required></label><label>專案代號<input v-model="projectForm.code" placeholder="website" pattern="[a-zA-Z0-9_-]{2,32}" required></label><label class="grow">本機資料夾<div class="project-directory-field"><input v-model="projectForm.path" placeholder="請選擇專案資料夾" readonly required @click="directoryPickerTarget='project'"><button type="button" class="secondary" @click="directoryPickerTarget='project'"><Folder :size="16"/>選擇資料夾</button></div></label><button class="secondary" :disabled="busy">新增專案</button><div class="project-create-option"><small>從預設位置瀏覽，也可在選擇視窗內建立新資料夾。選取後按「新增專案」完成登錄。</small></div></form></section>
        <section v-if="store.user.role==='admin'" class="panel settings-card wide"><h2><Users :size="20"/>成員與專案授權</h2><div v-for="u in users" :key="u.id" class="member-row"><span class="avatar">{{u.name.slice(0,1)}}</span><div><strong>{{u.name}}</strong><small>{{u.username}} · {{u.role==='admin'?'管理者':'成員'}}</small></div><div v-if="u.role!=='admin'" class="member-projects"><label v-for="p in store.projects" :key="p.id"><input v-model="u.projectIds" type="checkbox" :value="p.id" @change="run(()=>api(`/admin/users/${u.id}/projects`,{projectIds:u.projectIds}))">{{p.name}}</label></div></div><form class="inline-form" @submit.prevent="run(async()=>{await api('/admin/users',memberForm);users=await api('/admin/users');Object.assign(memberForm,{name:'',username:'',password:'',projectIds:[]});notify('成員已建立；請在上方分配專案');})"><label>姓名<input v-model="memberForm.name" required></label><label>帳號<input v-model="memberForm.username" pattern="[a-zA-Z0-9_-]{3,40}" required></label><label>初始密碼<input v-model="memberForm.password" type="password" minlength="12" autocomplete="new-password" placeholder="至少 12 字元" required></label><button class="secondary">新增成員</button></form></section>
        <section class="panel settings-card"><h2><ShieldCheck :size="20"/>變更密碼</h2><form @submit.prevent="run(async()=>{await api('/account/password',passwordForm);passwordForm.current='';passwordForm.password='';notify('密碼已更新');})"><label>目前密碼<input v-model="passwordForm.current" type="password" autocomplete="current-password" required></label><label>新密碼<input v-model="passwordForm.password" type="password" autocomplete="new-password" minlength="12" placeholder="至少 12 字元" required></label><button class="secondary">更新密碼</button></form></section><section class="panel settings-card"><h2><ShieldCheck :size="20"/>執行邊界</h2><ul class="boundaries"><li>每份計畫需由任務擁有者或管理者核准。</li><li>修改需求後，舊版核准失效。</li><li>每輪修正需先審核方案，單次執行最多 30 分鐘。</li><li>發布核准會記錄成果版本，對外發布仍需人工執行。</li><li>此版本僅供可信任成員與專案使用；工作副本不等於作業系統沙箱。</li></ul></section></div>
      </template>
      <footer class="page-footer"><span>TaskFlow / 本地優先，進度透明</span><span>每 3 秒同步 · {{store.projects.length}} 個專案</span></footer>
    </main></div>
  </div>
  <div v-if="showNew" class="modal-backdrop" @click.self="showNew=false"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="create-title"><header><div><span class="eyebrow">NEW TASK</span><h2 id="create-title">你想完成什麼？</h2></div><button class="icon-button" title="關閉" @click="showNew=false"><X/></button></header><form @submit.prevent="create"><label>任務標題<input v-model="newTask.title" placeholder="用一句話描述預期成果" minlength="2" maxlength="140" required autofocus></label><div class="form-grid"><label>所屬專案<select v-model="newTask.projectId" required><option v-if="store.user.role==='admin'" value="__new__">依任務標題建立新專案（預設）</option><option disabled value="">選擇專案</option><option v-for="p in store.projects" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>任務類型<select v-model="newTask.type"><option value="code">程式開發</option><option value="research">研究與文件</option></select></label></div><p v-if="newTask.projectId==='__new__'" class="subtle">送出時在 {{store.defaultProjectRoot||'尚未設定的預設位置'}} 建立新專案。名稱使用任務標題；特殊字元會轉換，同名時加上編號。</p><label>需求與驗收期待<textarea v-model="newTask.description" rows="5" minlength="5" maxlength="16000" placeholder="描述背景、需要完成的事情、限制與如何確認成功。也可以貼上參考連結。" required/></label><div class="form-grid"><label>優先級<select v-model="newTask.priority"><option v-for="(p,i) in priorities" :key="i" :value="i">{{p}}</option></select></label><label>根節點規劃<select v-model="newTask.planner"><option value="claude">Claude Code</option><option value="codex">Codex</option></select></label><label>執行引擎<select v-model="newTask.executor"><option value="codex">Codex</option><option value="claude">Claude Code</option></select></label><label>驗證引擎<select v-model="newTask.reviewer"><option value="claude">Claude Code</option><option value="codex">Codex</option></select></label></div><div class="notice"><ShieldCheck :size="18"/>AI 先整理計畫，經你核准後才執行。</div><div class="modal-actions"><button type="button" class="secondary" @click="showNew=false">取消</button><button class="primary" :disabled="busy||(!newTask.projectId)||(newTask.projectId==='__new__'&&!store.defaultProjectRoot)"><Plus :size="17"/>發布任務</button></div><p v-if="!store.projects.length&&store.user.role!=='admin'" class="error-text">請先在設定中新增或取得專案授權。</p></form></section></div>
  <div v-if="selected" class="drawer-backdrop" @click.self="selected=null"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="detail-title"><header class="drawer-header"><span class="eyebrow">TASK / {{selected.id.slice(0,8)}}</span><button class="icon-button" title="關閉詳情" @click="selected=null"><X/></button></header><div class="drawer-title"><span class="badge" :class="selected.status">{{statuses[selected.status]}}</span><h2 id="detail-title">{{selected.title}}</h2><p>{{selected.projectName}} · {{selected.ownerName}} · {{time(selected.created)}}</p></div><div class="drawer-tabs"><button v-for="item in [{id:'overview',label:'需求與計畫'},{id:'threads',label:'角色紀錄'},{id:'activity',label:'活動紀錄'},{id:'artifacts',label:'成果檔案'}]" :key="item.id" :class="{active:tab===item.id}" @click="tab=item.id">{{item.label}}</button></div><div class="drawer-body"><div v-if="selected.status==='rate_limited'" class="notice">{{selected.retryEngine}} 額度限制，預計 {{new Date(selected.retryAt).toLocaleString('zh-TW',{timeZone:selected.retryTimeZone})}}（{{selected.retryTimeZone}}）自動重試目前步驟。暫停或取消任務可停止自動重試。</div><div v-if="selected.manualCompletion" class="notice">此任務由使用者手動完成，不代表已通過 AI 驗證。</div><label>任務狀態<select :value="selected.status" :disabled="busy" @change="setTaskStatus(selected,$event)"><option :value="selected.status">{{selected.manualCompletion?'手動完成':statuses[selected.status]}}</option><option v-if="selected.status!=='completed'" value="completed">標記完成</option><option v-if="selected.status!=='paused'" value="paused">暫停任務</option><option v-if="selected.status!=='cancelled'" value="cancelled">取消任務</option><option v-if="['completed','cancelled','paused','failed','waiting_input'].includes(selected.status)" value="reopen">恢復處理</option></select></label>
    <div v-if="selected.error" class="notice warning">{{selected.error}}</div><section v-if="selected.environmentIssue" class="questions"><h3>套件環境處理方案待審核</h3><p class="prewrap">{{selected.environmentIssue.message}}</p><button v-if="selected.status==='waiting_input'" class="primary" :disabled="busy" @click="run(()=>api(`/tasks/${selected.id}/preflight/retry`,{issueId:selected.environmentIssue.id}))">環境已處理，核准重新檢查</button><p>檢查通過才繼續已核准的步驟；更換套件須在下方補充需求並重新審核計畫。</p></section><section v-if="selected.outputIssue" class="questions"><h3>回傳格式處理方案待審核</h3><p class="prewrap">{{selected.outputIssue.message}}</p><p>已保留原始結果與已完成進度。請在下方補充缺失內容或重新規劃的處理要求；新計畫仍須核准，不會自動重跑本次工作。</p></section>
    <template v-if="tab==='overview'"><ValidationSkip :request="selected.validationSkipRequest" :skips="selected.validationSkips" :busy="busy" @decide="decision=>run(()=>api(`/tasks/${selected.id}/validation/decision`,{requestId:selected.validationSkipRequest.id,decision}))"/><section v-if="selected.validationFailure" class="questions"><h3>最近未通過的驗證：第 {{selected.round}} 輪修正</h3><p class="prewrap">{{selected.validationFailure.summary}}</p><ul><li v-for="(e,i) in selected.validationFailure.evidence" :key="i">{{e}}</li></ul><p v-if="!selected.validationFailure.evidence.length">驗證缺少可確認的證據。</p><p v-for="(q,i) in selected.validationFailure.questions" :key="i">待確認：{{q}}</p><p v-if="selected.status==='repair_planning'">正在唯讀分析原因與解法，尚未執行修正。</p><template v-if="selected.repairPlan"><h3>問題原因與修正方案</h3><p class="prewrap">{{selected.repairPlan.summary}}</p><div v-for="(step,i) in selected.repairPlan.steps" :key="i" class="plan-step"><span class="step-number">{{Number(i)+1}}</span><div><strong>{{step.title}}</strong><p>{{step.instructions}}</p></div></div><h3>重新驗證標準</h3><ul><li v-for="(item,i) in selected.repairPlan.acceptance" :key="i">{{item}}</li></ul><p v-for="(q,i) in selected.repairPlan.questions" :key="i">待確認：{{q}}</p><template v-if="selected.status==='awaiting_repair_approval'&&!selected.validationSkipRequest"><button class="primary full" :disabled="busy||selected.repairPlan.questions.length>0" @click="run(()=>api(`/tasks/${selected.id}/repair/approve`,{proposalId:selected.repairPlan.id}))">核准此修正方案並執行</button><form @submit.prevent="run(async()=>{await api(`/tasks/${selected.id}/repair/revise`,{proposalId:selected.repairPlan.id,answer});answer='';})"><label>補充或修改修正方案<textarea v-model="answer" rows="3" minlength="2" maxlength="8000" required/></label><button class="secondary" :disabled="busy">重新提出方案，待我審核</button></form></template></template></section><h3>原始需求</h3><p class="prewrap requirement">{{selected.description}}</p><div v-if="!selected.plan" class="notice"><Clock3 :size="18"/>{{store.runner.enabled?'根節點將依順序整理計畫。':'AI 執行服務目前暫停；啟用後才會整理計畫。'}}</div><template v-else><div class="section-heading"><h3>執行計畫</h3><span class="count">v{{selected.planVersion}}</span></div><p class="prewrap">{{selected.plan.summary}}</p><h3>驗收條件</h3><ul class="acceptance"><li v-for="(a,i) in selected.plan.acceptance" :key="i"><ShieldCheck :size="16"/>{{a}}</li></ul><h3>角色與步驟</h3><div v-for="(step,i) in selected.plan.steps" :key="i" class="plan-step"><span class="step-number">{{Number(i)+1}}</span><div><strong>{{step.title}}</strong><small>{{step.role}} · {{selected.executor}}</small><p>{{step.instructions}}</p></div></div><div class="plan-step"><span class="step-number"><Check :size="16"/></span><div><strong>獨立驗證</strong><small>{{selected.reviewer}} · 檢查所有驗收條件</small></div></div><button v-if="selected.status==='awaiting_approval'" class="primary full" :disabled="busy" @click="run(()=>api(`/tasks/${selected.id}/approve`,{version:selected.planVersion}))"><ShieldCheck :size="18"/>核准計畫 v{{selected.planVersion}} 並加入執行佇列</button></template><ExecutionApproval v-if="selected.executionApproval" :request="selected.executionApproval" :busy="busy" @decide="decision=>run(()=>api(`/tasks/${selected.id}/execution/decision`,{requestId:selected.executionApproval.id,decision}))"/><div v-if="selected.questions.length&&!selected.executionApproval&&!selected.validationSkipRequest" class="questions"><h3>需要你確認</h3><p v-for="(q,i) in selected.questions" :key="i">{{Number(i)+1}}. {{q}}</p></div><form v-if="!selected.validationSkipRequest&&!selected.executionApproval&&['waiting_input','awaiting_approval','paused','failed'].includes(selected.status)" @submit.prevent="run(async()=>{await api(`/tasks/${selected.id}/revise`,{answer});answer='';})"><label>回答問題或補充需求<textarea v-model="answer" rows="3" minlength="2" maxlength="8000" required placeholder="補充後會建立新版計畫，重新請你審核。"/></label><button class="secondary" :disabled="busy">送出補充並重新規劃</button></form></template>
    <template v-if="tab==='threads'"><div v-if="!selected.threads.length" class="empty"><GitBranch/><p>尚未開始工作。</p></div><details v-for="th in selected.threads" :key="th.id" class="thread-detail" :open="th.status==='running'"><summary><span class="engine-mark">{{th.engine==='codex'?'C':'A'}}</span><div class="grow"><strong>{{th.role}}</strong><small>{{th.engine}} · {{duration(th)}}</small></div><span class="badge" :class="th.displayStatus||th.status">{{th.statusLabel||statuses[th.status]}}</span></summary><p class="prewrap">{{th.summary||th.error||'執行中，尚未回傳結果。'}}</p><h4 v-if="th.result?.evidence?.length">驗證證據</h4><ul><li v-for="(e,i) in th.result?.evidence||[]" :key="i">{{e}}</li></ul><small v-if="th.sessionId">工作階段：{{th.sessionId}}</small><div class="thread-log" v-for="event in selected.events.filter((e:any)=>e.thread_id===th.id).slice(-15)" :key="event.seq"><time>{{time(event.at)}}</time><p>{{event.message}}</p></div></details></template>
    <template v-if="tab==='activity'"><div class="timeline"><div v-for="event in [...selected.events].reverse()" :key="event.seq" class="timeline-event"><i/><div><time>{{time(event.at)}} · {{event.kind}}</time><p class="prewrap">{{event.message}}</p></div></div></div></template>
    <template v-if="tab==='artifacts'"><div class="notice"><Folder :size="18"/>工作副本中的檔案（含原始專案），最多顯示 500 個。原專案不會自動被覆寫。</div><p v-if="!files.length" class="muted">尚未建立工作副本。</p><a v-for="file in files" :key="file.path" :href="`/api/tasks/${selected.id}/download?path=${encodeURIComponent(file.path)}`" class="file-row"><FileText :size="17"/><span>{{file.path}}</span><small>{{Math.ceil(file.size/1024)}} KB</small><Download :size="16"/></a><div v-if="selected.status==='completed'&&!selected.manualCompletion&&selected.artifactVersion" class="publish-box"><h3>成果交付</h3><p>核准會綁定這次成果版本。此版本不會自動部署、合併或對外發送，需由負責人手動交付。</p><button v-if="!selected.publishApproval" class="secondary" @click="action('publish-approve')"><ShieldCheck :size="17"/>核准此版本交付</button><span v-else class="badge completed">此版本已核准，等待人工交付</span></div></template>
  </div><footer class="drawer-footer"><span>計畫 v{{selected.planVersion}} · {{selected.completedSteps}} / {{selected.totalSteps}} 步驟</span><div><button v-if="['planning','queued','running'].includes(selected.status)" class="secondary compact" @click="action('pause')"><Pause :size="15"/>暫停派工</button><button v-if="selected.threads.some((t:any)=>t.status==='running')" class="secondary compact danger" @click="action('stop')"><Square :size="14"/>中止</button><button v-if="['paused','failed'].includes(selected.status)" class="secondary compact" @click="action('resume')"><Play :size="15"/>恢復</button><button v-if="!['completed','cancelled'].includes(selected.status)" class="icon-button danger" title="取消任務" @click="action('cancel')"><X :size="18"/></button></div></footer></section></div>
  <div v-if="toast" class="toast" role="status"><AlertCircle :size="18"/>{{toast}}<button class="icon-button" title="關閉通知" @click="toast=''"><X :size="16"/></button></div>
</template>
